// supabase/functions/get-live-order-state/index.ts

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { fetchWithTimeout } from "../_shared/http.ts";
import { getSignedRiderImageUrl } from "../_shared/signed_url_cache.ts";
import { getEtaWithBudget } from "../_shared/eta_cache.ts";
import { olaRequest } from "../_shared/ola_client.ts";
import { singleRelation } from "../_shared/single_relation.ts";

function buildOrderSnapshot(order: Record<string, unknown>) {
  return {
    // Version 2 omits unsupported legacy fee columns and preserves nullable DB values.
    contract_version: 2,
    id: order.id,
    updated_at: order.updated_at,
    order_code: order.order_code,
    user_id: order.user_id,
    rider_id: order.rider_id,
    order_type: order.order_type,
    vehicle_type: order.vehicle_type,
    order_status: order.order_status,
    distance_meters: order.distance_meters,
    distance_km: order.distance_km,
    estimated_duration_min: order.estimated_duration_min,
    actual_duration_min: order.actual_duration_min,
    time_taken_seconds: order.time_taken_seconds,
    pickup_address: order.pickup_address,
    pickup_lat: order.pickup_lat,
    pickup_lng: order.pickup_lng,
    destination_address: order.destination_address,
    destination_lat: order.destination_lat,
    destination_lng: order.destination_lng,
    actual_fare: order.actual_fare,
    current_fare: order.current_fare,
    final_fare: order.final_fare,
    base_fare: order.base_fare,
    distance_fare: order.distance_fare,
    time_fare: order.time_fare,
    waiting_charge: order.waiting_charge,
    platform_fee: order.platform_fee,
    payment_mode: order.payment_mode,
    payment_status: order.payment_status,
    payment_id: order.payment_id,
    fare_payment_method: order.fare_payment_method,
    fare_payment_attempted_at: order.fare_payment_attempted_at,
    pickup_otp: order.pickup_otp,
    delivery_otp: order.delivery_otp,
    parcel_type: order.parcel_type,
    receiver_name: order.receiver_name,
    receiver_phone: order.receiver_phone,
    weight_category: order.weight_category,
    actual_weight_kg: order.actual_weight_kg,
    parcel_images: order.parcel_images ?? [],
    special_instructions: order.special_instructions,
    created_at: order.created_at,
    accepted_at: order.accepted_at,
    rider_arrived_at: order.rider_arrived_at,
    picked_up_at: order.picked_up_at,
    rider_at_drop_at: order.rider_at_drop_at,
    completed_at: order.completed_at,
    cancelled_at: order.cancelled_at,
    boost_amount: order.boost_amount,
    boost_percentage: order.boost_percentage,
    pickup_city: order.pickup_city,
    destination_city: order.destination_city,
    travel_date: order.travel_date,
    seats_requested: order.seats_requested,
    trip_started_at: order.trip_started_at,
    gst_percentage: order.gst_percentage,
    gst_amount: order.gst_amount,
    commission_percentage: order.commission_percentage,
    commission_amount: order.commission_amount,
    rider_earning: order.rider_earning,
    boost_company_earning: order.boost_company_earning,
    boost_rider_earning: order.boost_rider_earning,
  };
}

serve(async (req) => {
  try {
    // ---------------------------------------------------
    // CORS
    // ---------------------------------------------------

    if (req.method === "OPTIONS") {
      return new Response("ok", {
        headers: {
          "Access-Control-Allow-Origin": "*",
          "Access-Control-Allow-Headers":
            "authorization, x-client-info, apikey, content-type",
        },
      });
    }

    // ---------------------------------------------------
    // ENV VARIABLES
    // ---------------------------------------------------

    const supabaseUrl =
      Deno.env.get("SUPABASE_URL")!;

    const supabaseAnonKey =
      Deno.env.get("SUPABASE_ANON_KEY")!;

    const serviceRoleKey =
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

    // "oauth" (default) calls Ola Maps via OLA_CLIENT_ID/OLA_CLIENT_SECRET OAuth (see
    // _shared/ola_client.ts). Set to "api_key" (`supabase secrets set OLA_AUTH_MODE=api_key`) to
    // instantly revert to the pre-OAuth OLA_MAPS_API_KEY query-param path with zero redeploy, if
    // OAuth needs to be rolled back before it's been fully validated in production.
    const olaAuthMode =
      Deno.env.get("OLA_AUTH_MODE") ?? "oauth";

    // ---------------------------------------------------
    // AUTH HEADER
    // ---------------------------------------------------

    const authHeader =
      req.headers.get("Authorization");

    if (!authHeader) {
      return new Response(
        JSON.stringify({
          success: false,
          error: "Missing authorization header",
        }),
        {
          status: 401,
          headers: {
            "Content-Type": "application/json",
          },
        }
      );
    }

    // ---------------------------------------------------
    // USER CLIENT
    // ---------------------------------------------------

    const supabaseUserClient =
      createClient(
        supabaseUrl,
        supabaseAnonKey,
        {
          global: {
            headers: {
              Authorization: authHeader,
            },
          },
        }
      );

    // ---------------------------------------------------
    // ADMIN CLIENT
    // ---------------------------------------------------

    const supabaseAdmin =
      createClient(
        supabaseUrl,
        serviceRoleKey
      );

    // ---------------------------------------------------
    // BODY
    // ---------------------------------------------------

    const body = await req.json();

    const orderId = body.order_id;

    // ---------------------------------------------------
    // AUTH USER + GET ORDER -- run concurrently (Phase 10E 2E).
    //
    // The JWT-validation round trip and the embedded order fetch are independent: the order query
    // is a service-role read that never uses `user`, and the ownership check further below still
    // runs only after both resolve. One Promise.all removes a serial round trip from every ~5s
    // live-order poll. Guard precedence is unchanged (401 auth -> 400 order_id -> 404 -> 403); the
    // query is skipped when order_id is absent, and the embedded select below (order + rider +
    // rider_kyc + rider's user profile in one round trip) is unchanged. Same auth+fetch pattern
    // as update-order-status / accept-order / calculate-order-pricing.
    // ---------------------------------------------------

    const [
      { data: { user }, error: authError },
      { data: order, error: orderError },
    ] = await Promise.all([
      supabaseUserClient.auth.getUser(),
      orderId
        ? supabaseAdmin
        .from("orders")
        .select(`
          id,
          updated_at,
          order_code,
          order_status,
          order_type,
          pickup_address,
          pickup_lat,
          pickup_lng,
          destination_address,
          destination_lat,
          destination_lng,
          rider_id,
          user_id,
          vehicle_type,
          pickup_otp,
          delivery_otp,
          created_at,
          distance_meters,
          distance_km,
          estimated_duration_min,
          actual_duration_min,
          time_taken_seconds,
          actual_fare,
          current_fare,
          final_fare,
          base_fare,
          distance_fare,
          time_fare,
          waiting_charge,
          platform_fee,
          payment_mode,
          payment_status,
          payment_id,
          fare_payment_method,
          fare_payment_attempted_at,
          parcel_type,
          receiver_name,
          receiver_phone,
          weight_category,
          actual_weight_kg,
          parcel_images,
          special_instructions,
          accepted_at,
          rider_arrived_at,
          picked_up_at,
          rider_at_drop_at,
          completed_at,
          cancelled_at,
          boost_amount,
          boost_percentage,
          pickup_city,
          destination_city,
          travel_date,
          seats_requested,
          trip_started_at,
          gst_percentage,
          gst_amount,
          commission_percentage,
          commission_amount,
          rider_earning,
          boost_company_earning,
          boost_rider_earning,
          riders (
            id,
            rating,
            current_lat,
            current_lng,
            current_heading,
            last_location_updated_at,
            user_id,
            rider_kyc!riders_kyc_id_fkey (
              vehicle_number,
              rider_image,
              vehicle_type
            ),
            users!riders_user_id_fkey (
              id,
              full_name,
              phone
            )
          )
        `)
        .eq("id", orderId)
        .single()
        : Promise.resolve({ data: null, error: null }),
    ]);

    if (authError || !user) {
      return new Response(
        JSON.stringify({
          success: false,
          error: "Unauthorized user",
        }),
        {
          status: 401,
          headers: {
            "Content-Type": "application/json",
          },
        }
      );
    }

    if (!orderId) {
      return new Response(
        JSON.stringify({
          success: false,
          error: "order_id is required",
        }),
        {
          status: 400,
          headers: {
            "Content-Type": "application/json",
          },
        }
      );
    }

    if (orderError || !order) {
      return new Response(
        JSON.stringify({
          success: false,
          error: "Order not found",
        }),
        {
          status: 404,
          headers: {
            "Content-Type": "application/json",
          },
        }
      );
    }

    // ---------------------------------------------------
    // SECURITY CHECK
    // ---------------------------------------------------

    if (order.user_id !== user.id) {
      return new Response(
        JSON.stringify({
          success: false,
          error: "Access denied",
        }),
        {
          status: 403,
          headers: {
            "Content-Type": "application/json",
          },
        }
      );
    }

    // Construct only after authentication and explicit ownership authorization.
    // This is an allowlisted raw orders snapshot; rider/travel-plan display
    // enrichment remains in the existing order/rider response objects below.
    const orderSnapshot = buildOrderSnapshot(order);

    // ---------------------------------------------------
    // RIDER NOT ASSIGNED
    // ---------------------------------------------------

    if (!order.rider_id) {
      return new Response(
        JSON.stringify({
          success: true,
          rider_assigned: false,
          order_snapshot: orderSnapshot,
          order: {
            id: order.id,
            order_code: order.order_code,
            order_status: order.order_status,
            pickup_address:
              order.pickup_address,
            destination_address:
              order.destination_address,
            vehicle_type:
              order.vehicle_type,
          },
        }),
        {
          status: 200,
          headers: {
            "Content-Type": "application/json",
          },
        }
      );
    }

    // `order.riders` is populated by the embedded select above; the earlier "RIDER NOT ASSIGNED"
    // branch already returned when order.rider_id was null, so it is guaranteed non-null here
    // (a null embed alongside a non-null rider_id would indicate the rider row itself is missing,
    // preserved below with the same "Rider not found" 404 the old separate fetch produced).
    const riderRow = singleRelation(order.riders);
    const rider = riderRow ? {
      ...riderRow,
      users: singleRelation(riderRow.users),
      rider_kyc: singleRelation(riderRow.rider_kyc),
    } : null;

    if (!rider) {
      return new Response(
        JSON.stringify({
          success: false,
          error: "Rider not found",
        }),
        {
          status: 404,
          headers: {
            "Content-Type": "application/json",
          },
        }
      );
    }

    const riderUser = rider.users ?? null;

    console.log(
      "LIVE_STATUS stage=rider_profile category=resolved"
    );

    // ---------------------------------------------------
    // PHASE A (A2): rider live GPS -- PRIMARY public.rider_locations, FALLBACK the
    // embedded riders.current_* above.
    //
    // rider_locations is one-row-per-rider (rider_id PK), kept in sync with riders
    // by the A1 bridge trigger today and made the fresh high-frequency source by the
    // A3 Flutter writer; riders.current_* stays as a low-frequency compatibility
    // mirror (still read by dispatch / find_nearby_riders, unchanged here). This is
    // one small service-role point read (rider_id = PK), isolated: if it errors or
    // the row is missing / has no usable coordinates, `hasUsableRiderLocation` is
    // false and every downstream consumer falls back to exactly the riders.* values
    // used before A2 -- response shape, null handling and data exposed are identical
    // (rider_locations exposes the same four GPS fields riders already did).
    // ---------------------------------------------------
    const { data: riderLocationRow } = await supabaseAdmin
      .from("rider_locations")
      .select("current_lat, current_lng, current_heading, last_location_updated_at")
      .eq("rider_id", order.rider_id)
      .maybeSingle();

    const hasUsableRiderLocation =
      riderLocationRow != null &&
      riderLocationRow.current_lat != null &&
      riderLocationRow.current_lng != null;

    const effectiveRiderLat: number | null =
      hasUsableRiderLocation ? riderLocationRow!.current_lat : (rider.current_lat ?? null);
    const effectiveRiderLng: number | null =
      hasUsableRiderLocation ? riderLocationRow!.current_lng : (rider.current_lng ?? null);
    const effectiveRiderHeading: number | null =
      hasUsableRiderLocation ? riderLocationRow!.current_heading : (rider.current_heading ?? null);
    const effectiveRiderLocationUpdatedAt: string | null =
      hasUsableRiderLocation
        ? riderLocationRow!.last_location_updated_at
        : (rider.last_location_updated_at ?? null);

    // ---------------------------------------------------
    // ENRICHMENT: signed rider photo URL, the OLA Maps ETA, and the intercity plan vehicle-type
    // lookup are all independent of each other and of everything already fetched above -- run
    // concurrently. R7 perf fix: the intercity lookup used to be awaited sequentially before this
    // Promise.all even started, even though it depends only on order.order_type/orderId/rider.id
    // (already resolved above) and nothing here depends on its result -- folding it in removes one
    // full DB round trip from the critical path for intercity orders. Same query, same filters,
    // same null fallback, same downstream usage; only when it runs relative to the other two
    // changed. Both cache-backed lookups are also routed through short-lived isolate-scoped caches
    // (_shared/signed_url_cache.ts, _shared/eta_cache.ts) so repeated 5s polls for the same order
    // don't each pay for a fresh storage-sign call or a fresh OLA Maps round trip; same final
    // values, same fallback-on-error behavior either way -- only how often the underlying work
    // actually happens changed.
    // ---------------------------------------------------
    const [resolvedRiderImage, etaResult, intercityPlanVehicleType] = await Promise.all([
      // RESOLVE RIDER PHOTO (P1-2 fix: rider_kyc bucket is now private -- a stored
      // value may be either the OLD full public-URL shape or a NEW bare storage path;
      // either way it must be turned into a fresh signed URL here, server-side, using
      // supabaseAdmin (service-role, unaffected by storage RLS) so the client never
      // needs its own signed-URL round trip for this field.
      (async (): Promise<string | null> => {
        const storedRiderImage: string | null = rider.rider_kyc?.rider_image ?? null;
        if (!storedRiderImage) return null;
        const publicUrlMarker = "/storage/v1/object/public/rider_kyc/";
        const storagePath = storedRiderImage.includes(publicUrlMarker)
          ? storedRiderImage.split(publicUrlMarker).pop()!
          : (storedRiderImage.startsWith("http://") || storedRiderImage.startsWith("https://"))
            ? null
            : storedRiderImage;
        if (!storagePath) return null;
        return await getSignedRiderImageUrl(supabaseAdmin, storagePath);
      })(),

      // ETA CALCULATION USING OLA MAPS -- own try/catch preserved exactly as before (a slow/failed
      // OLA call must never fail the whole response, unchanged).
      // getEtaWithBudget adds a short-TTL cache + a 2s race bound in front of this same fetch --
      // see _shared/eta_cache.ts for why fetchFresh must throw (not return a value) on failure.
      getEtaWithBudget(orderId, async () => {
          // A2: rider_locations-first, riders.* fallback (resolved above).
          const riderLat = effectiveRiderLat;
          const riderLng = effectiveRiderLng;
          const pickupLat = order.pickup_lat;
          const pickupLng = order.pickup_lng;
          try {
            // deno-lint-ignore no-explicit-any
            let etaData: any;
            if (olaAuthMode === "api_key") {
              // Legacy path, preserved byte-for-byte -- see OLA_AUTH_MODE comment above.
              const olaApiKey = Deno.env.get("OLA_MAPS_API_KEY") ?? "";
              const etaResponse = await fetchWithTimeout(
                `https://api.olamaps.io/routing/v1/distanceMatrix/basic?origins=${riderLat},${riderLng}&destinations=${pickupLat},${pickupLng}&api_key=${olaApiKey}`,
                {
                  method: "GET",
                  headers: {
                    "X-Request-Id": crypto.randomUUID(),
                  },
                },
                8000,
              );
              etaData = await etaResponse.json();
              if (!etaResponse.ok) {
                const apiMessage = (etaData && (etaData.error_message || etaData.message || etaData.status)) || "no error detail in body";
                throw new Error(`OLA API HTTP error ${etaResponse.status}: ${apiMessage}`);
              }
            } else {
              // OAuth path (default): getOlaAccessToken()/olaRequest() handle token
              // acquisition/caching/retry and throw an HttpError with a safe message on failure --
              // caught below exactly like the legacy branch's thrown Error.
              etaData = await olaRequest("/routing/v1/distanceMatrix/basic", {
                query: {
                  origins: `${riderLat},${riderLng}`,
                  destinations: `${pickupLat},${pickupLng}`,
                },
                timeoutMs: 8000,
              });
            }
            console.log("LIVE_STATUS stage=eta category=response_received");

            // DEFENSIVE VALIDATION (OLA ETA parsing crash fix, 2026-08-08): the unguarded
            // `etaData.rows[0].elements[0]` access below crashed with a generic, unactionable
            // TypeError on every single call in the latest real-device session (25/25 failures) --
            // an HTTP error response from OLA (bad/expired key, quota, rejected request) and a
            // differently-shaped success body both land here with no usable `rows` array, and were
            // previously indistinguishable from each other or from a genuine parsing bug. Each
            // branch below now throws a specific, descriptive error instead of letting the access
            // crash, so the *reason* is captured in the caught error's message below -- no raw
            // response-body log access needed to tell the causes apart. The catch block's re-throw,
            // getEtaWithBudget's fallback, and the success-path computation/shape below are all
            // unchanged.
            const rows = etaData?.rows;
            if (!Array.isArray(rows) || rows.length === 0) {
              const apiMessage = (etaData && (etaData.error_message || etaData.message || etaData.status)) || "rows missing/empty";
              throw new Error(`OLA ETA response has no rows: ${apiMessage}`);
            }

            const elements = rows[0]?.elements;
            if (!Array.isArray(elements) || elements.length === 0) {
              throw new Error("OLA ETA response row has no elements");
            }

            const element = elements[0];
            if (!element || typeof element.distance !== "number" || typeof element.duration !== "number") {
              const elementStatus = element?.status ?? "unknown";
              throw new Error(`OLA ETA element missing distance/duration (status: ${elementStatus})`);
            }

            return {
              distanceKm: element.distance / 1000,
              estimatedArrivalMinutes: Math.max(1, Math.round(element.duration / 60)),
            };
          } catch (etaError) {
            console.error("LIVE_STATUS stage=eta category=calculation_failed");
            // Re-throw (rather than returning a zero fallback here) so getEtaWithBudget's own
            // cache-miss fallback runs -- serving the last good cached ETA instead of clobbering
            // it with a zero for the full cache TTL after one transient OLA failure. If there is
            // no cache yet, getEtaWithBudget itself returns the identical zero-value fallback.
            throw etaError;
          }
        }),

      // INTERCITY VEHICLE TYPE (Issue 3 fix): orders.vehicle_type for an intercity_ride/
      // intercity_parcel order is the PASSENGER'S preference captured at request-creation time
      // (create-order/index.ts normalizes it to 'any'/'bike'/'auto'/'cab' before a traveller is
      // even matched) -- it is never the traveller's actual vehicle, so it must never be shown to
      // the passenger as "the rider's vehicle". Once a traveller is matched, rider_travel_plans.
      // vehicle_type (the specific plan/vehicle the traveller published and the passenger actually
      // booked onto) is the authoritative value -- rider_kyc.vehicle_type is not used here because
      // a traveller can own or be KYC-verified for a different vehicle than the one they published
      // for this particular trip. Scoped strictly to intercity order types so local ride/parcel
      // vehicle_type (which IS already the real, dispatch-matched vehicle) is completely unaffected.
      (async (): Promise<string | null> => {
        if (order.order_type === "intercity_ride" || order.order_type === "intercity_parcel") {
          const { data: intercityRequest } = await supabaseAdmin
            .from("intercity_requests")
            .select("rider_travel_plans!intercity_requests_route_id_fkey(vehicle_type)")
            .eq("parcel_id", orderId)
            .eq("traveller_id", rider.id)
            .not("route_id", "is", null)
            .order("updated_at", { ascending: false })
            .limit(1)
            .maybeSingle();

          return (intercityRequest as { rider_travel_plans?: { vehicle_type?: string | null } | null } | null)
            ?.rider_travel_plans?.vehicle_type ?? null;
        }
        return null;
      })(),
    ]);

    const { distanceKm, estimatedArrivalMinutes, degraded: etaDegraded } = etaResult;

    // ---------------------------------------------------
    // RESPONSE
    // ---------------------------------------------------

    return new Response(
      JSON.stringify({
        success: true,

        rider_assigned: true,
        order_snapshot: orderSnapshot,

        order: {
          id: order.id,
          order_code:
            order.order_code,
          order_status:
            order.order_status,

          pickup_address:
            order.pickup_address,

          pickup_lat:
            order.pickup_lat,

          pickup_lng:
            order.pickup_lng,

          destination_address:
            order.destination_address,

          destination_lat:
            order.destination_lat,

          destination_lng:
            order.destination_lng,

          vehicle_type:
            intercityPlanVehicleType ?? order.vehicle_type,

          created_at:
            order.created_at,
        },

        rider: {
          id: rider.id,

         name:
  riderUser?.full_name ??
  "Waydrop Rider",

phone:
  riderUser?.phone ?? "",

          image:
            resolvedRiderImage,

          vehicle_number:
            rider.rider_kyc
              ?.vehicle_number ?? null,

          vehicle_type:
            intercityPlanVehicleType ?? rider.rider_kyc?.vehicle_type ?? null,

          rating:
            rider.rating,
        },

        live_location: {
          // A2: rider_locations-first, riders.* fallback (resolved above).
          latitude:
            effectiveRiderLat,

          longitude:
            effectiveRiderLng,

          heading:
            effectiveRiderHeading,

          updated_at:
            effectiveRiderLocationUpdatedAt,
        },

        tracking: {
          distance_to_pickup_km:
            Number(
              distanceKm.toFixed(2)
            ),

          estimated_arrival_minutes:
            estimatedArrivalMinutes,

          // P1 fix (ETA failure must not break live ride status): true only when the ETA
          // provider (OLA Maps) failed or didn't answer in time and the value above is a
          // fallback (last-known-good cache, or 0/0 if there's no cache yet) rather than a
          // fresh reading -- order/rider/status data above this point is completely unaffected
          // either way. Omitted (undefined, not false) on a normal successful ETA so existing
          // clients that don't read this field see byte-for-byte the same shape as before.
          tracking_degraded:
            etaDegraded === true ? true : undefined,
        },
      }),
      {
        status: 200,
        headers: {
          "Content-Type":
            "application/json",

          "Access-Control-Allow-Origin":
            "*",
        },
      }
    );

  } catch {

    console.error(
      "LIVE_STATUS stage=request category=unexpected_failure"
    );

    return new Response(
      JSON.stringify({
        success: false,
        error: "Unable to retrieve live order status",
      }),
      {
        status: 500,
        headers: {
          "Content-Type":
            "application/json",
        },
      }
    );
  }
});

// Shared helper: fetchWithTimeout
//
// ROOT CAUSE (WayDrop Progressive Degradation Audit, finding EDGE-1): none of this codebase's edge
// functions ever set a timeout or AbortController on an outbound fetch() -- Ola Maps, Cashfree,
// Google OAuth/FCM, and internal function-to-function calls all block for however long the peer
// takes, bounded only by the platform's own opaque gateway timeout. A 20-40s stall on a mobile
// network is already indistinguishable from "never returns" to a user watching a spinner, and
// surfaces client-side as an unbounded wait or a raw connection abort.
//
// This wraps `fetch` with an AbortController-driven timeout so every caller gets a bounded,
// catchable failure (a DOMException named "AbortError") instead of an unbounded hang, while
// leaving the request/response shape, headers, and body completely unchanged for the success path.
export async function fetchWithTimeout(
  input: string | URL | Request,
  init: RequestInit = {},
  timeoutMs = 15000,
): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(input, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

export function isTimeoutError(error: unknown): boolean {
  return error instanceof Error && error.name === "AbortError";
}

// For calls that don't go through fetch() directly (e.g. supabase.functions.invoke(), which does
// not accept an AbortSignal across all supabase-js versions this project has pinned to). Bounds how
// long the caller waits; it does not cancel the underlying in-flight request server-side, but it
// guarantees this function's own response is never held hostage by an unbounded downstream call.
export async function withTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number,
  timeoutMessage = "Operation timed out",
): Promise<T> {
  let timer: ReturnType<typeof setTimeout>;
  const timeoutPromise = new Promise<never>((_, reject) => {
    timer = setTimeout(() => {
      const err = new Error(timeoutMessage);
      err.name = "AbortError";
      reject(err);
    }, timeoutMs);
  });
  try {
    return await Promise.race([promise, timeoutPromise]);
  } finally {
    clearTimeout(timer!);
  }
}

// Shared helper: getSignedRiderImageUrl
//
// Isolate-scoped cache for signed rider-KYC-image URLs used by get-live-order-status. The
// underlying signed URL is valid for 21600s (6h); this function is polled every ~5s per active
// order, so without caching, every single poll pays for a fresh Supabase Storage sign operation
// for a URL that is still valid from the previous poll. Cache entries are kept for TTL_MS, safely
// under the real 21600s validity window, so a cached URL returned here is never actually expired.

const SIGN_EXPIRY_SECONDS = 21600;
const TTL_MS = 5.5 * 60 * 60 * 1000; // 5.5h -- comfortably under the 6h real expiry.

const cache = new Map<string, { url: string; cachedAt: number }>();

export async function getSignedRiderImageUrl(
  // deno-lint-ignore no-explicit-any
  supabaseAdmin: any,
  storagePath: string,
): Promise<string | null> {
  const cached = cache.get(storagePath);
  if (cached && Date.now() - cached.cachedAt < TTL_MS) {
    return cached.url;
  }

  const { data: signedData } = await supabaseAdmin.storage
    .from("rider_kyc")
    .createSignedUrl(storagePath, SIGN_EXPIRY_SECONDS);

  const url = signedData?.signedUrl ?? null;
  if (url) {
    cache.set(storagePath, { url, cachedAt: Date.now() });
  }
  return url;
}

// Shared helper: getEtaWithBudget
//
// Isolate-scoped, short-TTL cache + bounded race for the OLA Maps ETA lookup used by
// get-live-order-status. This function is polled every ~5s per active order from both the
// passenger and rider client -- calling OLA fresh on every single poll is both unnecessary
// (a rider's ETA doesn't need sub-20s precision) and, per the WayDrop Progressive Degradation
// investigation, a source of avoidable per-request latency sitting in the response's critical
// path. Two changes from the old inline behavior:
//
//   1. A successful OLA result is cached per order_id for TTL_MS and reused across polls in that
//      window, instead of calling OLA fresh every single time.
//   2. A fresh lookup (cache miss/expired) is raced against a short bound (RACE_TIMEOUT_MS, well
//      under OLA's own 8s request timeout). If OLA hasn't answered within that bound, the
//      response is returned immediately using the last cached value (if any) rather than waiting
//      -- OLA's own call is left running in the background and will populate the cache for the
//      *next* poll if it eventually succeeds.
//
// `fetchFresh` is expected to THROW on failure (not return a zero-value fallback itself) -- that
// is what lets a single transient OLA failure fall back to the last good cached value instead of
// overwriting it with a stale-looking zero for the full TTL window. The caller's own zero-value
// fallback ({distanceKm: 0, estimatedArrivalMinutes: 0}) is only ever used here when there is no
// cached value at all to fall back to -- identical to today's cold-start behavior.

type EtaResult = { distanceKm: number; estimatedArrivalMinutes: number; degraded?: boolean };

const TTL_MS = 20_000;
const RACE_TIMEOUT_MS = 2_000;

const cache = new Map<string, { value: EtaResult; cachedAt: number }>();

export async function getEtaWithBudget(
  orderId: string,
  fetchFresh: () => Promise<EtaResult>,
): Promise<EtaResult> {
  const cached = cache.get(orderId);
  const now = Date.now();
  if (cached && now - cached.cachedAt < TTL_MS) {
    return cached.value;
  }

  const freshPromise = fetchFresh()
    .then((value) => {
      cache.set(orderId, { value, cachedAt: Date.now() });
      return value;
    })
    .catch(() => null);

  const timeoutFallback = new Promise<null>((resolve) => {
    setTimeout(() => resolve(null), RACE_TIMEOUT_MS);
  });

  const raced = await Promise.race([freshPromise, timeoutFallback]);
  if (raced) return raced;

  // P1 fix (ETA failure must not break live ride status): the fresh lookup either failed
  // (caught above) or didn't answer within the race window -- order/rider/status data is still
  // returned normally by the caller either way (this function already never throws), but the
  // ETA value itself is now a fallback, not a real reading. `degraded: true` lets the caller
  // surface that distinction to the client instead of silently presenting a stale/zero ETA as
  // current.
  if (cached) return { ...cached.value, degraded: true };
  return { distanceKm: 0, estimatedArrivalMinutes: 0, degraded: true };
}

// Shared helper: getOlaAccessToken / olaRequest
//
// Ola Maps OAuth 2.0 (client-credentials) token acquisition + authenticated request helper for
// any edge function that calls api.olamaps.io on the server side. Token endpoint, grant type,
// and header format are Ola Krutrim's documented OAuth 2.0 flow (maps.olakrutrim.com/docs/auth,
// cross-checked against Ola's own published Postman collection and SDK source, since the docs
// page itself renders the exact values inside copy-to-clipboard widgets that aren't present in a
// plain fetch): POST to a Keycloak-backed token endpoint with
// grant_type=client_credentials, then `Authorization: Bearer <access_token>` on the Maps API
// calls themselves (no api_key query param needed once using OAuth). Re-verify against the
// Ola Krutrim developer portal if the first live token/API call in Step 8 testing fails.
//
// OLA_CLIENT_ID / OLA_CLIENT_SECRET are read only via Deno.env.get() -- never logged, never
// echoed in any thrown error message, and never returned to the Flutter client. The access token
// itself is also never returned to the client; it only ever travels from this module straight
// into the Authorization header of a server-side request to api.olamaps.io.

import { fetchWithTimeout, isTimeoutError } from "./http.ts";
import { HttpError } from "./http_errors.ts";

const OLA_TOKEN_URL =
  "https://account.olamaps.io/realms/olamaps/protocol/openid-connect/token";
const OLA_API_BASE = "https://api.olamaps.io";
const TOKEN_REQUEST_TIMEOUT_MS = 8000;
// Refresh a little before the token's real expiry so an in-flight request never races a token
// that goes stale mid-request.
const EXPIRY_SAFETY_MARGIN_MS = 60_000;
// If Ola's response is missing/malformed expires_in, assume a conservative short lifetime rather
// than caching an unknown-duration token indefinitely.
const FALLBACK_TTL_SECONDS = 300;

type CachedToken = { accessToken: string; expiresAt: number };

// Isolate-scoped in-memory cache only (same pattern as eta_cache.ts / signed_url_cache.ts) --
// never persisted to disk, KV, or the database, so it cannot leak via any storage layer and is
// automatically gone when the isolate recycles.
let cachedToken: CachedToken | null = null;
// Collapses concurrent cold-start callers onto a single in-flight token request instead of firing
// N parallel OAuth calls the first time N requests land in the same warm isolate at once.
let inFlightTokenRequest: Promise<string> | null = null;

function readOlaCredentials(): { clientId: string; clientSecret: string } {
  const clientId = Deno.env.get("OLA_CLIENT_ID");
  const clientSecret = Deno.env.get("OLA_CLIENT_SECRET");

  if (!clientId || !clientSecret) {
    throw new HttpError(
      500,
      "Ola Maps OAuth is not configured on the server.",
      "OLA_OAUTH_NOT_CONFIGURED",
    );
  }

  return { clientId, clientSecret };
}

async function requestNewAccessToken(): Promise<string> {
  const { clientId, clientSecret } = readOlaCredentials();

  let response: Response;
  try {
    response = await fetchWithTimeout(
      OLA_TOKEN_URL,
      {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          grant_type: "client_credentials",
          scope: "openid",
          client_id: clientId,
          client_secret: clientSecret,
        }).toString(),
      },
      TOKEN_REQUEST_TIMEOUT_MS,
    );
  } catch (networkError) {
    console.error(
      "OLA OAUTH TOKEN REQUEST FAILED =>",
      isTimeoutError(networkError) ? "timeout" : "network_failure",
    );
    throw new HttpError(
      502,
      "Could not reach Ola Maps authentication service.",
      "OLA_OAUTH_NETWORK_ERROR",
    );
  }

  // deno-lint-ignore no-explicit-any
  let body: any;
  try {
    body = await response.json();
  } catch {
    throw new HttpError(
      502,
      "Ola Maps authentication service returned a malformed response.",
      "OLA_OAUTH_MALFORMED_RESPONSE",
    );
  }

  if (!response.ok) {
    // error / error_description are standard OAuth error fields, never the credentials
    // themselves -- the credentials were only ever in the outbound request body, which this
    // catch block never logs.
    console.error(`OLA OAUTH TOKEN HTTP ERROR status=${response.status}`);

    // A 401/403 here means OUR client_id/client_secret were rejected -- that is a server
    // misconfiguration, not something the calling passenger/rider did, so it is surfaced to
    // Flutter as a generic 500 rather than a 401/403 (which would misleadingly suggest the
    // end-user's own session/auth is the problem).
    throw new HttpError(
      response.status === 401 || response.status === 403 ? 500 : 502,
      "Ola Maps authentication failed.",
      "OLA_OAUTH_REJECTED",
    );
  }

  const accessToken = body?.access_token;
  if (typeof accessToken !== "string" || accessToken.length === 0) {
    throw new HttpError(
      502,
      "Ola Maps authentication service did not return an access token.",
      "OLA_OAUTH_NO_TOKEN",
    );
  }

  const expiresIn = typeof body?.expires_in === "number" && body.expires_in > 0
    ? body.expires_in
    : FALLBACK_TTL_SECONDS;

  cachedToken = {
    accessToken,
    expiresAt: Date.now() + expiresIn * 1000,
  };

  return accessToken;
}

/** Returns a valid Ola Maps OAuth access token, reusing a cached one until it's close to expiry. */
export async function getOlaAccessToken(): Promise<string> {
  if (cachedToken && Date.now() < cachedToken.expiresAt - EXPIRY_SAFETY_MARGIN_MS) {
    return cachedToken.accessToken;
  }

  if (!inFlightTokenRequest) {
    inFlightTokenRequest = requestNewAccessToken().finally(() => {
      inFlightTokenRequest = null;
    });
  }

  return inFlightTokenRequest;
}

export interface OlaRequestOptions {
  method?: string;
  query?: Record<string, string | number | undefined>;
  timeoutMs?: number;
  headers?: Record<string, string>;
}

/**
 * Makes an OAuth-authenticated request to an Ola Maps API endpoint (path relative to
 * https://api.olamaps.io, e.g. "/routing/v1/distanceMatrix/basic"). Automatically fetches/caches
 * the access token and retries exactly once with a forced-fresh token if Ola rejects it as
 * expired/invalid (401/403), so a token that expires between our cache check and Ola's own
 * validation doesn't surface as a hard failure. Throws HttpError with a safe, secret-free message
 * on any failure -- callers should let that propagate to their own catch block (see
 * http_errors.ts's httpErrorResponse) or handle it explicitly for a graceful-degradation path.
 */
export async function olaRequest(
  path: string,
  options: OlaRequestOptions = {},
): Promise<unknown> {
  const url = new URL(path.startsWith("http") ? path : `${OLA_API_BASE}${path}`);
  if (options.query) {
    for (const [key, value] of Object.entries(options.query)) {
      if (value !== undefined) url.searchParams.set(key, String(value));
    }
  }

  for (let attempt = 1; attempt <= 2; attempt++) {
    const accessToken = await getOlaAccessToken();

    let response: Response;
    try {
      response = await fetchWithTimeout(
        url.toString(),
        {
          method: options.method ?? "GET",
          headers: {
            "Authorization": `Bearer ${accessToken}`,
            "X-Request-Id": crypto.randomUUID(),
            ...options.headers,
          },
        },
        options.timeoutMs ?? 8000,
      );
    } catch (networkError) {
      console.error(
        "OLA API REQUEST FAILED =>",
        isTimeoutError(networkError) ? "timeout" : "network_failure",
      );
      throw new HttpError(
        isTimeoutError(networkError) ? 504 : 502,
        isTimeoutError(networkError) ? "Ola Maps request timed out." : "Could not reach Ola Maps.",
        isTimeoutError(networkError) ? "OLA_API_TIMEOUT" : "OLA_API_NETWORK_ERROR",
      );
    }

    if ((response.status === 401 || response.status === 403) && attempt === 1) {
      // Our cached token was rejected -- force a fresh one and retry exactly once.
      cachedToken = null;
      continue;
    }

    // deno-lint-ignore no-explicit-any
    let body: any;
    try {
      body = await response.json();
    } catch {
      throw new HttpError(
        502,
        "Ola Maps returned a malformed response.",
        "OLA_API_MALFORMED_RESPONSE",
      );
    }

    if (!response.ok) {
      const apiMessage = body?.error_message ?? body?.message ?? body?.status ??
        "no error detail in body";
      console.error(`OLA API HTTP ERROR status=${response.status}`);

      throw new HttpError(
        response.status === 429 ? 429 : response.status >= 500 ? 502 : 500,
        `Ola Maps API error (${response.status}): ${apiMessage}`,
        "OLA_API_ERROR",
      );
    }

    return body;
  }

  // Unreachable in practice (the loop always returns or throws above) -- satisfies the compiler
  // and gives a safe, generic failure if it ever were reached.
  throw new HttpError(502, "Ola Maps request failed.", "OLA_API_ERROR");
}

// Minimal typed error so a known business-logic outcome (invalid transition, concurrent-request
// conflict, invalid OTP, authorization failure) can carry its own correct HTTP status/code through
// a thrown exception, instead of being flattened into a generic 500 by a catch-all at the bottom
// of the function -- which is misleading to callers/monitoring and indistinguishable from an
// actual server bug.
//
// Usage: `throw new HttpError(409, "Order status changed by another request. Please retry.", "CONFLICT");`
// then, in the function's outer catch: `if (error instanceof HttpError) { ...use error.status/code... }`.
// Anything NOT thrown as an HttpError falls through to the existing generic 500 path unchanged --
// this only reclassifies errors that were already being intentionally thrown for a known reason.
export class HttpError extends Error {
  readonly status: number;
  readonly code?: string;

  constructor(status: number, message: string, code?: string) {
    super(message);
    this.name = "HttpError";
    this.status = status;
    this.code = code;
  }
}

// Shared response builder so every function formats an HttpError (or an unexpected exception) the
// same way: { success: false, error, code? } with the right status, never a blanket 500 for a
// known condition.
export function httpErrorResponse(
  error: unknown,
  corsHeaders: Record<string, string>,
): Response {
  if (error instanceof HttpError) {
    return new Response(
      JSON.stringify({
        success: false,
        error: error.message,
        ...(error.code ? { code: error.code } : {}),
      }),
      {
        status: error.status,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      },
    );
  }

  // A malformed request body (`req.json()` throwing) is a client mistake, not a server failure --
  // was previously indistinguishable from a genuine crash once it fell into a catch-all 500.
  if (error instanceof SyntaxError) {
    return new Response(
      JSON.stringify({ success: false, error: "Malformed request body" }),
      { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }

  return new Response(
    JSON.stringify({
      success: false,
      // deno-lint-ignore no-explicit-any
      error: (error as any)?.message ?? String(error) ?? "Unknown error",
    }),
    {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    },
  );
}

// Supabase's ungenerated relation types may infer arrays for to-one embeds.
// Preserve object/null responses and refuse ambiguous multi-row relations.
export function singleRelation<T>(value: T | T[] | null): T | null {
  if (Array.isArray(value)) return value.length === 1 ? value[0] : null;
  return value;
}
